// Perspective projection function
// Projects a 3D point to 2D screen coordinates
function project(pt) {
  let d = 60.0; // Camera distance
  var h = 1.5; // Eye height
  let alfa = radians(30); // Rotation angle around Y-axis

  // Rotate around Y-axis
  let a = pt.x * sin(alfa) - pt.z * cos(alfa);
  var b = pt.x * cos(alfa) + pt.z * sin(alfa);

  // Perspective projection
  let x = d * a / (b + d);
  var y = d * (pt.y - h) / (b + d);

  // Scale and position on screen
  let sc = height / 90;
  return createVector(0.63 * width + sc * x, 0.95 * height - sc * y);
}

// Draw a simple box in perspective with filled faces
function drawBox(pos, w, h, d, mainColor, windowColor, topOffsets, windowType) {
  // Calculate 8 corners of the box
  // Bottom vertices stay at ground level (no offset)
  let corners = [
    createVector(pos.x, pos.y, pos.z),           // 0: bottom-front-left
    createVector(pos.x + w, pos.y, pos.z),       // 1: bottom-front-right
    createVector(pos.x + w, pos.y, pos.z + d),   // 2: bottom-back-right
    createVector(pos.x, pos.y, pos.z + d),       // 3: bottom-back-left
    // Top vertices with random offsets for skewing
    createVector(pos.x + topOffsets.frontLeft.x, pos.y + h, pos.z + topOffsets.frontLeft.z),       // 4: top-front-left
    createVector(pos.x + w + topOffsets.frontRight.x, pos.y + h, pos.z + topOffsets.frontRight.z),   // 5: top-front-right
    createVector(pos.x + w + topOffsets.backRight.x, pos.y + h, pos.z + d + topOffsets.backRight.z), // 6: top-back-right
    createVector(pos.x + topOffsets.backLeft.x, pos.y + h, pos.z + d + topOffsets.backLeft.z)    // 7: top-back-left
  ];

  // Project all corners to 2D
  let projected = corners.map(c => project(c));

  noStroke();

  // Draw the 6 faces of the box (non-visible faces first)
  // Bottom face (vertices 0, 1, 2, 3)
  fill(mainColor.h, mainColor.s, mainColor.b);
  beginShape();
  vertex(projected[0].x, projected[0].y);
  vertex(projected[1].x, projected[1].y);
  vertex(projected[2].x, projected[2].y);
  vertex(projected[3].x, projected[3].y);
  endShape(CLOSE);

  // Top face (vertices 4, 5, 6, 7)
  beginShape();
  vertex(projected[4].x, projected[4].y);
  vertex(projected[5].x, projected[5].y);
  vertex(projected[6].x, projected[6].y);
  vertex(projected[7].x, projected[7].y);
  endShape(CLOSE);

  // Back face (vertices 2, 3, 7, 6)
  beginShape();
  vertex(projected[2].x, projected[2].y);
  vertex(projected[3].x, projected[3].y);
  vertex(projected[7].x, projected[7].y);
  vertex(projected[6].x, projected[6].y);
  endShape(CLOSE);

  // Right face (vertices 1, 2, 6, 5)
  beginShape();
  vertex(projected[1].x, projected[1].y);
  vertex(projected[2].x, projected[2].y);
  vertex(projected[6].x, projected[6].y);
  vertex(projected[5].x, projected[5].y);
  endShape(CLOSE);

  // Front and left faces with texture using clipping
  push();

  // Create clipping mask for both front and left faces
  beginClip();
  // Front face (vertices 0, 1, 5, 4)
  beginShape();
  vertex(projected[0].x, projected[0].y);
  vertex(projected[1].x, projected[1].y);
  vertex(projected[5].x, projected[5].y);
  vertex(projected[4].x, projected[4].y);
  endShape(CLOSE);
  // Left face (vertices 0, 3, 7, 4)
  beginShape();
  vertex(projected[0].x, projected[0].y);
  vertex(projected[3].x, projected[3].y);
  vertex(projected[7].x, projected[7].y);
  vertex(projected[4].x, projected[4].y);
  endShape(CLOSE);
  endClip();

  // Calculate bounding box for the two faces
  let xCoords = [projected[0].x, projected[1].x, projected[3].x, projected[4].x, projected[5].x, projected[7].x];
  let yCoords = [projected[0].y, projected[1].y, projected[3].y, projected[4].y, projected[5].y, projected[7].y];
  let minX = min(xCoords);
  let maxX = max(xCoords);
  let minY = min(yCoords);
  let maxY = max(yCoords);

  // Draw base color
  fill(mainColor.h, mainColor.s, mainColor.b);
  rect(minX, minY, maxX - minX, maxY - minY);

  // Draw texture rectangles with HSB variations
  let numRects = 400 + floor(random(10));
  for (let i = 0; i < numRects; i++) {
    var x = random(minX, maxX);
    var y = random(minY, maxY);
    let rectW = random(20, 100);
    let rectH = random(20, 100);

    // Vary HSB components slightly
    let hVar = mainColor.h + random(-5, 5);
    let sVar = constrain(mainColor.s + random(-10, 10), 0, 100);
    let bVar = constrain(mainColor.b + random(-15, 15), 0, 100);

    fill(hVar, sVar, bVar, random(5, 10));
    // rect(x, y, rectW, rectH);
    // Add some randomness to the quad points
    let quadPoints = [
      createVector(x, y),
      createVector(x + rectW, y),
      createVector(x + rectW, y + rectH),
      createVector(x, y + rectH),
    ];
    let n = 30
    quadPoints = quadPoints.map(p => {
      return createVector(p.x + random(-n, n), p.y + random(-n, n));
    });
    quad(quadPoints[0].x, quadPoints[0].y, quadPoints[1].x, quadPoints[1].y, quadPoints[2].x, quadPoints[2].y, quadPoints[3].x, quadPoints[3].y);
  }

  pop();

  // Draw borders and windows on front face
  const frontFacePoints = [
    [projected[0].x, projected[0].y],
    [projected[1].x, projected[1].y],
    [projected[5].x, projected[5].y],
    [projected[4].x, projected[4].y],
    [projected[0].x, projected[0].y] // close path
  ];
  rg.linearPath(frontFacePoints, {
    stroke: 'black',
    strokeWidth: 2,
    roughness: 1.2,
    bowing: 0.5
  });

  // Draw windows on front face
  if (windowType > 0) {
    drawWindowsOnFace([projected[0], projected[1], projected[5], projected[4]], windowType, w, h, windowColor);
  }

  // Draw borders and windows on left face
  const leftFacePoints = [
    [projected[0].x, projected[0].y],
    [projected[3].x, projected[3].y],
    [projected[7].x, projected[7].y],
    [projected[4].x, projected[4].y],
    [projected[0].x, projected[0].y] // close path
  ];
  rg.linearPath(leftFacePoints, {
    stroke: 'black',
    strokeWidth: 2,
    roughness: 1.2,
    bowing: 0.5
  });

  // Draw windows on left face
  if (windowType > 0) {
    drawWindowsOnFace([projected[0], projected[3], projected[7], projected[4]], windowType, d, h, windowColor);
  }
}

// Helper function to interpolate a point on a quadrilateral face
// u and v are parametric coordinates (0-1)
// faceVertices: [bottomLeft, bottomRight, topRight, topLeft]
function interpolateFacePoint(faceVertices, u, v) {
  // Bilinear interpolation on a quadrilateral
  let p0 = faceVertices[0]; // bottom-left
  let p1 = faceVertices[1]; // bottom-right
  let p2 = faceVertices[2]; // top-right
  let p3 = faceVertices[3]; // top-left

  // Interpolate bottom edge
  let bottom = createVector(
    lerp(p0.x, p1.x, u),
    lerp(p0.y, p1.y, u)
  );

  // Interpolate top edge
  let top = createVector(
    lerp(p3.x, p2.x, u),
    lerp(p3.y, p2.y, u)
  );

  // Interpolate between bottom and top
  return createVector(
    lerp(bottom.x, top.x, v),
    lerp(bottom.y, top.y, v)
  );
}

// Convert faceVertices format [BL, BR, TR, TL] to quad format [TL, TR, BR, BL]
function faceVerticesToQuad(faceVertices) {
  return [
    faceVertices[3], // TL
    faceVertices[2], // TR
    faceVertices[1], // BR
    faceVertices[0]  // BL
  ];
}

// Bilinear mapping (u,v)->point on quad (adapted from panels.js)
// u: left->right, v: top->bottom
function quadPoint(q, u, v) {
  var top = lerpPoint(q[0], q[1], u);
  const bot = lerpPoint(q[3], q[2], u);
  return lerpPoint(top, bot, v);
}

function lerpPoint(a, b, t) {
  return { x: lerp(a.x, b.x, t), y: lerp(a.y, b.y, t) };
}

// Approx width/height of the quad (average of opposite edges)
function quadSizeApprox(q) {
  const dist2 = (a, b) => {
    const dx = a.x - b.x, dy = a.y - b.y;
    return Math.sqrt(dx * dx + dy * dy);
  };
  var top = dist2(q[0], q[1]);
  var bottom = dist2(q[3], q[2]);
  const left = dist2(q[0], q[3]);
  const right = dist2(q[1], q[2]);
  return {
    w: (top + bottom) / 2,
    h: (left + right) / 2,
  };
}

// Draw a line of constant v (horizontal-ish), from u0..u1
function drawLineV(q, v, u0 = 0, u1 = 1, segments = 24, strokeColor = 'black') {
  const points = [];
  for (let i = 0; i <= segments; i++) {
    const u = lerp(u0, u1, i / segments);
    const p = quadPoint(q, u, v);
    points.push([p.x, p.y]);
  }
  rg.linearPath(points, {
    stroke: strokeColor,
    strokeWidth: 1,
    roughness: 1.2,
    bowing: 0.5
  });
}

// Draw a line of constant u (vertical-ish), from v0..v1
function drawLineU(q, u, v0 = 0, v1 = 1, segments = 24, strokeColor = 'black') {
  var points = [];
  for (let i = 0; i <= segments; i++) {
    const v = lerp(v0, v1, i / segments);
    var p = quadPoint(q, u, v);
    points.push([p.x, p.y]);
  }
  rg.linearPath(points, {
    stroke: strokeColor,
    strokeWidth: 1,
    roughness: 1.2,
    bowing: 0.5
  });
}

// Draw a skewed rectangle defined in (u,v) space
function drawUVRect(q, u0, v0, u1, v1, segments = 10, strokeColor = 'black') {
  var points = [];

  // Collect all points around the rectangle
  // top edge
  for (let i = 0; i <= segments; i++) {
    var u = lerp(u0, u1, i / segments);
    var p = quadPoint(q, u, v0);
    points.push([p.x, p.y]);
  }

  // right edge
  for (let i = 1; i <= segments; i++) {
    var v = lerp(v0, v1, i / segments);
    var p = quadPoint(q, u1, v);
    points.push([p.x, p.y]);
  }

  // bottom edge
  for (let i = 1; i <= segments; i++) {
    var u = lerp(u1, u0, i / segments);
    var p = quadPoint(q, u, v1);
    points.push([p.x, p.y]);
  }

  // left edge
  for (let i = 1; i < segments; i++) {
    var v = lerp(v1, v0, i / segments);
    var p = quadPoint(q, u0, v);
    points.push([p.x, p.y]);
  }

  // Close the path
  points.push(points[0]);

  rg.polygon(points, {
    stroke: strokeColor,
    strokeWidth: random(1, 3),
    roughness: 1.2,
    bowing: 0.5,
    fill: strokeColor,
  });
}

// Draw windows on a face accounting for skew
function drawWindowsOnFace(faceVertices, windowType, faceWidth, faceHeight, windowColor) {
  // Convert faceVertices format to quad format for panels.js functions
  const q = faceVerticesToQuad(faceVertices);

  // Convert window color to RGB for Rough.js
  colorMode(HSB, 360, 100, 100);
  let windowColorRGB = color(windowColor.h, windowColor.s, windowColor.b);
  colorMode(RGB, 255);
  let windowColorStr = `rgb(${red(window.color(windowColorRGB))}, ${green(window.color(windowColorRGB))}, ${blue(window.color(windowColorRGB))})`;

  if (windowType === 1) {
    drawHorizontalDividersWithBars(q, faceWidth, faceHeight, windowColorStr);
  } else if (windowType === 2) {
    drawGrid(q, faceWidth, faceHeight, windowColorStr);
  } else if (windowType === 3) {
    drawWindowRects(q, faceWidth, faceHeight, windowColorStr);
  }

  // Restore HSB mode
  colorMode(HSB, 360, 100, 100);
}

// Pattern 1: Horizontal dividers + vertical bars
function drawHorizontalDividersWithBars(q, faceWidth, faceHeight, strokeColor = 'black') {
  const opt = {
    minBandPx: 35,
    maxBandPx: 80,
    barMinPx: 10,
    barMaxPx: 30,
    barDensity: 0.75,
    marginUPx: 10,
    marginVPx: 10,
    bottomBlankMinPx: 0,
    bottomBlankMaxPx: 70,
    dividerJitterPx: 6,
  };

  const { w, h } = quadSizeApprox(q);

  const marginU = constrain(opt.marginUPx / w, 0, 0.25);
  const marginV = constrain(opt.marginVPx / h, 0, 0.25);

  const bottomBlank = random(opt.bottomBlankMinPx, opt.bottomBlankMaxPx) / h;

  // Where the decorative area ends (leave blank at bottom)
  const vEnd = constrain(1 - marginV - bottomBlank, 0, 1);
  const vStart = marginV;

  // Build horizontal bands
  var v = vStart;
  const bandCuts = [vStart];

  let _wG_2 = 0; while ((v < vEnd - 1e-6) && ++_wG_2 < 20000) {
    const bandPx = random(opt.minBandPx, opt.maxBandPx);
    const dv = bandPx / h;
    v = min(v + dv, vEnd);
    bandCuts.push(v);
  }

  // Draw the horizontal divider lines (between bands)
  for (let i = 0; i < bandCuts.length; i++) {
    const vv = bandCuts[i] + random(-opt.dividerJitterPx, opt.dividerJitterPx) / h;
    if (vv <= vStart + 1e-4 || vv >= vEnd - 1e-4) continue;
    drawLineV(q, constrain(vv, vStart, vEnd), marginU, 1 - marginU, 26, strokeColor);
  }

  // In each band, add some vertical bars
  for (let i = 0; i < bandCuts.length - 1; i++) {
    const v0 = bandCuts[i];
    const v1 = bandCuts[i + 1];

    const bandHeightPx = (v1 - v0) * h;
    // Skip tiny bands
    if (bandHeightPx < opt.minBandPx * 0.5) continue;

    // Decide bar width (in u-space)
    const barPx = random(opt.barMinPx, opt.barMaxPx);
    const du = barPx / w;

    // Fill across with bar "slots"
    var u = marginU;
    let _wG_3 = 0; while ((u < 1 - marginU - du) && ++_wG_3 < 20000) {
      if (random() < opt.barDensity) {
        const uu = u + random(-1, 1) * (opt.dividerJitterPx / w);
        drawLineU(q, constrain(uu, marginU, 1 - marginU), v0, v1, 18, strokeColor);
      }
      // Random spacing between bars
      const gapPx = random(opt.barMinPx * 0.6, opt.barMaxPx * 1.2);
      u += du + gapPx / w;
    }
  }
}

// Pattern 2: Grid
function drawGrid(q, faceWidth, faceHeight, strokeColor = 'black') {
  var opt = {
    cellMinPx: 25,
    cellMaxPx: 60,
    marginUPx: 10,
    marginVPx: 10,
    bottomBlankMinPx: 0,
    bottomBlankMaxPx: 40,
    jitterPx: 3,
  };

  const { w, h } = quadSizeApprox(q);

  var marginU = constrain(opt.marginUPx / w, 0, 0.25);
  var marginV = constrain(opt.marginVPx / h, 0, 0.25);
  var bottomBlank = random(opt.bottomBlankMinPx, opt.bottomBlankMaxPx) / h;

  var v0 = marginV;
  var v1 = constrain(1 - marginV - bottomBlank, 0, 1);
  const u0 = marginU;
  const u1 = 1 - marginU;

  // Choose cell size and derive counts
  const cellPx = random(opt.cellMinPx, opt.cellMaxPx);
  const cols = max(2, floor((w * (u1 - u0)) / cellPx));
  const rows = max(2, floor((h * (v1 - v0)) / cellPx));

  // Vertical lines
  for (let c = 1; c < cols; c++) {
    var u = lerp(u0, u1, c / cols) + random(-opt.jitterPx, opt.jitterPx) / w;
    drawLineU(q, constrain(u, u0, u1), v0, v1, 22, strokeColor);
  }

  // Horizontal lines
  for (let r = 1; r < rows; r++) {
    var v = lerp(v0, v1, r / rows) + random(-opt.jitterPx, opt.jitterPx) / h;
    drawLineV(q, constrain(v, v0, v1), u0, u1, 22, strokeColor);
  }
}

// Pattern 3: Window rectangles
function drawWindowRects(q, faceWidth, faceHeight, strokeColor = 'black') {
  var opt = {
    winMinPx: 18,
    winMaxPx: 45,
    gapMinPx: 6,
    gapMaxPx: 18,
    marginUPx: 14,
    marginVPx: 14,
    bottomBlankMinPx: 0,
    bottomBlankMaxPx: 70,
    insetMinPx: 2,
    insetMaxPx: 7,
    skipChance: 0.12,
    jitterPx: 2,
  };

  const { w, h } = quadSizeApprox(q);

  var marginU = constrain(opt.marginUPx / w, 0, 0.25);
  var marginV = constrain(opt.marginVPx / h, 0, 0.25);
  var bottomBlank = random(opt.bottomBlankMinPx, opt.bottomBlankMaxPx) / h;

  const U0 = marginU;
  const U1 = 1 - marginU;
  const V0 = marginV;
  const V1 = constrain(1 - marginV - bottomBlank, 0, 1);

  // Build columns with variable window widths + gaps (in px -> u)
  const colEdges = [U0];
  var u = U0;

  let _wG_4 = 0; while ((u < U1 - 1e-6) && ++_wG_4 < 20000) {
    const winW = random(opt.winMinPx, opt.winMaxPx);
    const gapW = random(opt.gapMinPx, opt.gapMaxPx);
    const duWin = winW / w;
    const duGap = gapW / w;

    // next edge after window
    const next = min(u + duWin, U1);
    if (next <= u + 1e-6) break;
    colEdges.push(next);

    u = min(next + duGap, U1);
    // start of next window
    if (u < U1 - 1e-6) colEdges.push(u);
  }

  // Convert colEdges into window intervals [u0,u1] by taking pairs
  var cols = [];
  for (let i = 0; i < colEdges.length - 1; i += 2) {
    var a = colEdges[i];
    var b = colEdges[i + 1];
    if (b - a > 0.01) cols.push([a, b]);
  }

  // Build rows similarly (v)
  const rowEdges = [V0];
  var v = V0;

  let _wG_5 = 0; while ((v < V1 - 1e-6) && ++_wG_5 < 20000) {
    const winH = random(opt.winMinPx, opt.winMaxPx);
    const gapH = random(opt.gapMinPx, opt.gapMaxPx);
    const dvWin = winH / h;
    const dvGap = gapH / h;

    var next = min(v + dvWin, V1);
    if (next <= v + 1e-6) break;
    rowEdges.push(next);

    v = min(next + dvGap, V1);
    if (v < V1 - 1e-6) rowEdges.push(v);
  }

  var rows = [];
  for (let i = 0; i < rowEdges.length - 1; i += 2) {
    var a = rowEdges[i];
    var b = rowEdges[i + 1];
    if (b - a > 0.01) rows.push([a, b]);
  }

  // Draw window rectangles: inset each cell by a small px amount
  for (const [vA, vB] of rows) {
    for (const [uA, uB] of cols) {
      if (random() < opt.skipChance) continue;

      const insetPx = random(opt.insetMinPx, opt.insetMaxPx);
      const duInset = insetPx / w;
      const dvInset = insetPx / h;

      var u0 = uA + duInset;
      var u1 = uB - duInset;
      var v0 = vA + dvInset;
      var v1 = vB - dvInset;

      // tiny jitter so it feels hand-drawn / imperfect
      u0 += random(-opt.jitterPx, opt.jitterPx) / w;
      u1 += random(-opt.jitterPx, opt.jitterPx) / w;
      v0 += random(-opt.jitterPx, opt.jitterPx) / h;
      v1 += random(-opt.jitterPx, opt.jitterPx) / h;

      // avoid inverted rects
      if (u1 <= u0 + 0.005 || v1 <= v0 + 0.005) continue;

      drawUVRect(q, u0, v0, u1, v1, 8, strokeColor);
    }
  }
}
